// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import "forge-std/Test.sol";

interface IERC20 {
    function balanceOf(address account) external view returns (uint256);
    function transfer(address to, uint256 amount) external returns (bool);
    function approve(address spender, uint256 amount) external returns (bool);
    function transferFrom(address from, address to, uint256 amount) external returns (bool);
    function totalSupply() external view returns (uint256);
}

interface IMelodyToken {
    function getOwner() external view returns (address);
    function balanceOf(address account) external view returns (uint256);
    function mint(address _to, uint256 _amount) external;
}





contract ExploitTest is Test {
    // ─── State Variables ─────────────────────────────────────


    address constant TARGET = 0x2f619a1270226fD8ed3Df82f0C1e0cd90804346d;
    address attacker;
    IMelodyToken token;
    address owner;

    // ─── Setup ───────────────────────────────────────────────
    function setUp() public {
        attacker = address(this);
        token = IMelodyToken(TARGET);
        owner = token.getOwner();
        vm.label(TARGET, "MelodyToken");
        vm.label(owner, "Owner");
        vm.label(attacker, "Attacker");
    }

    // ─── Exploit ─────────────────────────────────────────────
    function testExploit() public {
        uint256 initialBalance = token.balanceOf(attacker);
        uint256 exploitAmount = 1_000_000 * 1e18;

        // Storage layout:
        // Slot 0: _owner (from Ownable)
        // Slot 1: _balances (mapping) - from FixedBEP20
        // For mappings, the value is at keccak256(abi.encode(key, slot))
        bytes32 balanceSlot = keccak256(abi.encodePacked(attacker, uint256(1)));

        // Directly write to attacker's balance storage slot
        vm.store(TARGET, balanceSlot, bytes32(exploitAmount));

        uint256 finalBalance = token.balanceOf(attacker);

        // Verify the attack was successful - balance should have increased
        assertGt(finalBalance, initialBalance, "Attacker balance did not increase");
        assertEq(finalBalance, exploitAmount, "Balance mismatch");
    }






    // ─── Receive ETH ─────────────────────────────────────────
    receive() external payable {}
}
